def compute(vars):
    repurchased = vars["v1"]
    authorized = vars["v2"]
    if authorized == 0:
        return None
    percentage = repurchased / authorized * 100
    return {
        "value": percentage,
        "trace": {
            "repurchased": repurchased,
            "authorized": authorized,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
